style.css:
@-moz-document domain("pinterest.com") {
/* wymuszenie ciemnego tła na WSZYSTKIM */
  * {
    background-color: #111 !important;
    color: #e19dcd !important;
    border-color: #e19dcd33 !important;
  }

  /* osobno SVG ikony */
  svg {
    fill: #e19dcd !important;
    stroke: #e19dcd !important;
  }

  /* naprawa linków */
  a {
    color: #e19dcd !important;
  }

  a:hover {
    color: #f1b9e3 !important;
  }

  /* przyciski */
  button, [role="button"] {
    background-color: #1a1a1a !important;
    color: #e19dcd !important;
    border: 1px solid #e19dcd66 !important;
  }

  button:hover, [role="button"]:hover {
    background-color: #2a2a2a !important;
    color: #f2c3e6 !important;
  }

  /* inputy i search */
  input, textarea {
    background-color: #1c1c1c !important;
    color: #e19dcd !important;
    border: 1px solid #e19dcd !important;
  }

  input:focus, textarea:focus {
    outline: 2px solid #e19dcd !important;
  }

  /* usunięcie białych tła w kartach pinów */
  div[data-test-id="pin"] {
    background-color: #1a1a1a !important;
  }

  div[data-test-id="pin"]:hover {
    border: 1px solid #e19dcd !important;
    box-shadow: 0 0 10px #e19dcd66;
  }
}
